/**
 * groq/compound does not support custom function calling, so Glint uses a
 * text protocol: the model emits tool calls as sentinel-delimited JSON blocks.
 * Sentinels are chosen to never collide with compound's internal <tool> tags
 * or with markdown code fences.
 */

export const TOOL_OPEN = "<<<glint:tool";
export const TOOL_CLOSE = ">>>glint";

export interface ToolCall {
  tool: string;
  args: Record<string, unknown>;
  raw: string;
}

const BLOCK_RE = /^[ \t]*<<<glint:tool[ \t]*\r?\n([\s\S]*?)^[ \t]*>>>glint[ \t]*$/gm;

export function parseToolCalls(text: string): ToolCall[] {
  const calls: ToolCall[] = [];
  for (const match of text.matchAll(BLOCK_RE)) {
    const body = match[1].trim();
    const parsed = parseJsonLenient(body);
    if (parsed && typeof parsed.tool === "string") {
      calls.push({
        tool: parsed.tool,
        args: (parsed.args as Record<string, unknown>) ?? {},
        raw: match[0],
      });
    }
  }
  return calls;
}

export function stripToolBlocks(text: string): string {
  return text
    .replace(BLOCK_RE, "")
    .replace(/```\s*\n?\s*```/g, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/** Cut streamed text at the first tool sentinel so it never flashes on screen. */
export function visiblePrefix(streamed: string): string {
  const idx = streamed.indexOf(TOOL_OPEN);
  if (idx === -1) {
    // Hold back a partial sentinel at the tail (e.g. "<<<gli" mid-stream).
    for (let k = Math.min(TOOL_OPEN.length - 1, streamed.length); k > 0; k--) {
      if (streamed.endsWith(TOOL_OPEN.slice(0, k))) return streamed.slice(0, -k);
    }
    return streamed;
  }
  return streamed.slice(0, idx);
}

function parseJsonLenient(body: string): { tool?: string; args?: unknown } | null {
  const cleaned = body
    .replace(/^```(?:json)?\s*/m, "")
    .replace(/```\s*$/m, "")
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    const start = cleaned.indexOf("{");
    if (start === -1) return null;
    let depth = 0;
    let inStr = false;
    let esc = false;
    for (let i = start; i < cleaned.length; i++) {
      const ch = cleaned[i];
      if (esc) {
        esc = false;
        continue;
      }
      if (ch === "\\") {
        esc = true;
        continue;
      }
      if (ch === '"') inStr = !inStr;
      if (inStr) continue;
      if (ch === "{") depth++;
      if (ch === "}") {
        depth--;
        if (depth === 0) {
          try {
            return JSON.parse(cleaned.slice(start, i + 1));
          } catch {
            return null;
          }
        }
      }
    }
    return null;
  }
}

export function formatToolResults(
  results: Array<{ tool: string; status: "ok" | "error"; output: string }>,
): string {
  const parts = results.map(
    (r, i) =>
      `<glint:result n="${i + 1}" tool="${r.tool}" status="${r.status}">\n${r.output}\n</glint:result>`,
  );
  return `[tool results]\n${parts.join("\n")}`;
}
